import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n], b = new long[n];
        for (int k = 0; k < n; k++) a[k] = nextLong();
        for (int k = 0; k < n; k++) b[k] = nextLong();
        // Two pointers: always emit the smaller unused head.
        StringBuilder sb = new StringBuilder();
        int i = 0, j = 0;
        while (i < n && j < n) {
            if (a[i] <= b[j]) sb.append(a[i++]).append(' ');
            else sb.append(b[j++]).append(' ');
        }
        while (i < n) sb.append(a[i++]).append(' ');
        while (j < n) sb.append(b[j++]).append(' ');
        sb.setLength(sb.length() - 1);
        sb.append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	b := make([]int64, n)
	for k := range a {
		a[k] = nextInt()
	}
	for k := range b {
		b[k] = nextInt()
	}
	// Two pointers: always emit the smaller unused head.
	out := make([]byte, 0, 24*n)
	emit := func(v int64) {
		if len(out) > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, v, 10)
	}
	i, j := 0, 0
	for i < n && j < n {
		if a[i] <= b[j] {
			emit(a[i])
			i++
		} else {
			emit(b[j])
			j++
		}
	}
	for ; i < n; i++ {
		emit(a[i])
	}
	for ; j < n; j++ {
		emit(b[j])
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
